INSERT INTO `ai_embeddings` (`id`, `notebook_id`, `source_id`, `message_id`, `chunk_index`, `content_hash`, `embedding_model`, `token_count`, `content`, `embedding`, `metadata`, `created_at`, `updated_at`) VALUES
(1, 1, 1, NULL, 0, 'ce15c3e1b06c2826a179df217e1174dbfe3ac852', NULL, 27, 'Provincial risk assessment highlights delayed barangay reporting, uneven resource allocation, and inconsistent evacuation triggers. Recommended focus areas include budget alignment, floodgate readiness, and barangay communication escalation procedures.', NULL, '{\"source_name\":\"Provincial Risk Assessment 2026\",\"type\":\"pdf\"}', '2026-05-17 18:48:29', '2026-05-17 18:48:29'),
(2, 1, 2, NULL, 1, 'a24b0ec5662b89ec86a720080c000acaee05f41e', NULL, 26, 'Municipal coordination brief recommends a unified reporting template, clearer budget accountabilities, and synchronized operating timelines for LGUs. It also recommends standard action ownership and escalation checkpoints.', NULL, '{\"source_name\":\"Municipal Coordination Brief\",\"type\":\"docx\"}', '2026-05-17 18:48:29', '2026-05-17 18:48:29'),
(3, 1, 3, NULL, 2, 'f29ba932956b16b184c85200d42ea338452c5a41', NULL, 28, 'Meeting discussion emphasized communication bottlenecks, public advisory timing, and the need for an action tracker for field implementers. Participants requested a concise brief with lead offices and deadlines.', NULL, '{\"source_name\":\"Inter-Agency Meeting Recording\",\"type\":\"video\"}', '2026-05-17 18:48:29', '2026-05-17 18:48:29'),
