INSERT INTO `sources` (`id`, `notebook_id`, `uploaded_by`, `type`, `name`, `original_name`, `storage_disk`, `storage_path`, `source_url`, `mime_type`, `file_size`, `status`, `content_hash`, `metadata`, `summary`, `extracted_text`, `indexed_at`, `last_processed_at`, `created_at`, `updated_at`) VALUES
(1, 1, 2, 'pdf', 'Provincial Risk Assessment 2026', NULL, 'public', NULL, NULL, NULL, NULL, 'indexed', NULL, '{\"seeded\":true}', 'The assessment identifies delayed barangay reporting, uneven resource allocation, and a lack of synchronized evacuation triggers across municipalities.', 'Provincial risk assessment highlights delayed barangay reporting, uneven resource allocation, and inconsistent evacuation triggers. Recommended focus areas include budget alignment, floodgate readiness, and barangay communication escalation procedures.', '2026-05-17 18:48:29', '2026-05-17 18:48:29', '2026-05-17 18:48:29', '2026-05-17 18:48:29'),
(2, 1, 2, 'docx', 'Municipal Coordination Brief', NULL, 'public', NULL, NULL, NULL, NULL, 'indexed', NULL, '{\"seeded\":true}', 'The coordination brief proposes a unified reporting template, clearer budget accountabilities, and shared operating timelines for LGU teams.', 'Municipal coordination brief recommends a unified reporting template, clearer budget accountabilities, and synchronized operating timelines for LGUs. It also recommends standard action ownership and escalation checkpoints.', '2026-05-17 18:48:29', '2026-05-17 18:48:29', '2026-05-17 18:48:29', '2026-05-17 18:48:29'),
(3, 1, 2, 'video', 'Inter-Agency Meeting Recording', NULL, 'public', NULL, NULL, NULL, NULL, 'indexed', NULL, '{\"seeded\":true}', 'Meeting discussion emphasized communication bottlenecks, public advisory timing, and the need for a concise action tracker for local implementers.', 'Meeting discussion emphasized communication bottlenecks, public advisory timing, and the need for an action tracker for field implementers. Participants requested a concise brief with lead offices and deadlines.', '2026-05-17 18:48:29', '2026-05-17 18:48:29', '2026-05-17 18:48:29', '2026-05-17 18:48:29'),
